import {IDEAS,PHOTOS,TASKS,BUDGET_KEYS} from './data.js';
import {ROUTES,travelWindow,routeSchedule} from './routes.js';
import {createTravelHub} from './travel.js';
import {config} from './config.js';
import {escapeHTML as esc,cleanState,totalBudget,maps,nextRevision,safeURL,validateIdea} from './core.js';
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
const euro=new Intl.NumberFormat('de-AT',{style:'currency',currency:'EUR'});
const df=new Intl.DateTimeFormat('de-AT',{day:'2-digit',month:'2-digit',year:'numeric'});
let client,context=null,plan=cleanState({}),revision=null,ideas=IDEAS.map(i=>({...i})),votes=[],filter='all',dirty=false,saving=false,toastTimer,editing=null,ideaSaving=false,editorDirty=false,pendingKind=null;
const hub=createTravelHub({client:()=>client,context:()=>context,ideas:()=>ideas,toast,openLogin,onChange:()=>renderCatalog()});
const labels={flight:'Flug pro Person (€)',stay:'Unterkünfte für den gesamten Aufenthalt (€)',car:'Mietwagen gesamt (€)',road:'Sprit, Parken & Maut gesamt (€)',food:'Essen pro Person / Tag (€)',fun:'Eintritte pro Person (€)',extra:'Reserve für alle (€)'};
function toast(msg){$('#toast').textContent=msg;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),6000);}
function date(offset=0){if(!plan.start)return '';const d=new Date(plan.start+'T12:00:00');d.setDate(d.getDate()+offset);return df.format(d);}
function photo(i){return PHOTOS[i.photo_key]||PHOTOS.roadtrip;}
function author(i){return i.author_key?'Vorgeschlagen von '+(context?.people.find(p=>p.key===i.author_key)?.name||'einem Crewmitglied'):'Startvorschlag';}
function mine(i){return !!context&&votes.some(v=>v.idea_id===i.id&&v.member_key===context.me);}
function count(i){return votes.filter(v=>v.idea_id===i.id).length;}
function photoHTML(i,extra=''){const p=photo(i);return '<div class="idea-photo '+extra+'"><img src="'+esc(p.url)+'" alt="" loading="lazy" decoding="async" referrerpolicy="no-referrer"><div class="idea-shade"></div><div class="photo-caption"><span class="idea-badge">Vorschlag · '+esc(i.region)+'</span><h3>'+esc(i.title)+'</h3><p>'+esc(i.location)+'</p></div><small class="photo-motif">'+(i.kind==='hotel'?'Stadtmotiv: ':'Bildmotiv: ')+esc(p.label)+'</small></div>';}
function voteButton(i){return '<button class="vote-button" data-vote="'+esc(i.id)+'" aria-pressed="'+mine(i)+'" aria-label="'+esc(i.title)+': '+(mine(i)?'Favorit entfernen':'als Favorit markieren')+'">'+(mine(i)?'♥':'♡')+' '+(context?count(i)+' Favorit'+(count(i)===1?'':'en'):'Merken')+'</button>';}

function renderRoutes(){
 const fmt=iso=>df.format(new Date(iso+'T12:00:00Z'));
 const destination=key=>IDEAS.find(i=>i.id==='destination-'+key);
 $('#travel-windows').innerHTML=[10,12,14].map(days=>{const w=travelWindow(days);return '<tr><th scope="row">'+days+' Tage</th><td>'+w.nights+'</td><td>'+fmt(w.departUS)+'</td><td>'+fmt(w.home)+'</td></tr>';}).join('');
 $('#route-options').innerHTML=ROUTES.map(r=>{
  const w=routeSchedule(r),p=PHOTOS[r.photo];
  return '<article class="route-card"><div class="route-cover"><img src="'+esc(p.url)+'" alt="" loading="lazy" decoding="async" referrerpolicy="no-referrer"><div><span class="idea-badge">'+r.days+' Tage · '+w.nights+' Nächte</span><h3>'+esc(r.title)+'</h3><p>'+esc(r.tag)+'</p></div></div><div class="route-body"><p class="route-dates">'+fmt(w.start)+' – '+fmt(w.home)+'</p><p>'+esc(r.intro)+'</p><p class="route-path">'+w.stops.map(s=>esc(destination(s.key).title)).join(' → ')+'</p><p class="muted">'+esc(r.pace)+'</p><details><summary>Etappen & Übernachtungen ansehen</summary><ol class="route-stops">'+w.stops.map(s=>'<li><button class="quiet" data-detail="destination-'+esc(s.key)+'">'+esc(destination(s.key).title)+' →</button><span>'+fmt(s.arrival)+' – '+fmt(s.departure)+' · '+s.nights+' '+(s.nights===1?'Nacht':'Nächte')+'</span><p>'+esc(s.note)+'</p></li>').join('')+'</ol><p><strong>Optionale Zwischenstopps:</strong></p><div class="route-extras">'+r.optional.map(key=>'<button class="quiet" data-detail="destination-'+esc(key)+'">'+esc(destination(key).title)+' →</button>').join('')+'</div><p>'+esc(r.note)+'</p></details><p class="route-airports"><strong>Flugidee:</strong> Zürich → '+esc(r.airports[0])+' / zurück ab '+esc(r.airports[1])+'.<br>US-Abflug '+fmt(w.departUS)+', Heimkehr '+fmt(w.home)+'.</p><a href="#hotels">Passende Unterkünfte vergleichen →</a></div></article>';
 }).join('');
}

function renderCatalog(){
 for(const [kind,target,searchId] of [['destination','itinerary','destination-search'],['hotel','hotels','hotel-search']]){
  const q=$('#'+searchId).value.trim().toLocaleLowerCase('de');
  const list=ideas.filter(i=>!i.archived&&i.kind===kind&&(filter==='all'||(filter==='favorites'?mine(i):i.region===filter))&&[i.title,i.location,i.description].join(' ').toLocaleLowerCase('de').includes(q));
  $('#'+target).innerHTML=list.map(i=>'<article class="idea-card">'+photoHTML(i)+'<div class="idea-body"><small class="idea-author">'+esc(author(i))+'</small><p>'+esc(i.description)+'</p><div class="idea-actions"><button class="quiet" data-detail="'+esc(i.id)+'">Details →</button>'+voteButton(i)+'</div>'+hub.ideaMarkup(i)+(i.kind==='hotel'&&safeURL(i.url)?'<a class="hotel-link" href="'+esc(safeURL(i.url))+'" target="_blank" rel="noopener noreferrer">Zum Hotel ↗</a>':'')+(context&&i.author_key===context.me?'<div class="owner-actions"><button data-edit="'+esc(i.id)+'">Bearbeiten</button><button data-archive="'+esc(i.id)+'">Zurückziehen</button></div>':'')+'</div></article>').join('')||'<div class="empty-state"><h3>'+(!context&&filter==='favorites'?'Melde dich für deine Favoriten an.':'Noch kein passender Vorschlag.')+'</h3><p>Filter ändern oder eine eigene Idee ergänzen.</p><button class="button dark" data-add="'+kind+'">Vorschlag hinzufügen +</button></div>';
 }
 $('#destination-count').textContent=ideas.filter(i=>i.kind==='destination'&&!i.archived).length;
 $$('.catalog-status').forEach(el=>el.textContent=context?'Gemeinsame Sammlung · Ergänze eigene Ideen und markiere deine Favoriten.':'Startvorschläge · Melde dich an, um die Ideen der Gruppe zu sehen und eigene Vorschläge zu speichern.');
 renderGroup();
}
function showDetail(id){const i=ideas.find(i=>i.id===id&&!i.archived);if(!i)return;$('#idea-detail').innerHTML=photoHTML(i,'detail-photo')+'<p class="eyebrow">'+esc(author(i))+'</p><h2 id="detail-title">'+esc(i.title)+'</h2><p class="detail-description">'+esc(i.description)+'</p><p class="detail-tip">Unverbindlicher Vorschlag. '+(i.kind==='hotel'?'Preise, freie Zimmer und Bedingungen zum Reisetermin prüfen. Das Foto zeigt den Ort, nicht das Hotel.':'Ob und wann wir dieses Ziel besuchen, entscheiden wir gemeinsam.')+'</p><div class="dialog-links"><a href="'+esc(maps(i))+'" target="_blank" rel="noopener noreferrer">Auf der Karte ↗</a>'+(safeURL(i.url)?'<a href="'+esc(safeURL(i.url))+'" target="_blank" rel="noopener noreferrer">'+(i.kind==='hotel'?'Offizielle Website / Hotel':'Website zum Vorschlag')+' ↗</a>':'')+'</div><small class="muted">Foto: '+esc(photo(i).author)+' · <a href="'+esc(photo(i).source)+'" target="_blank" rel="noopener noreferrer">'+esc(photo(i).license)+'</a></small>';
 $('#idea-detail-dialog').setAttribute('aria-labelledby','detail-title');$('#idea-detail-dialog').showModal();
}
function route(scroll=true){let page=(location.hash.slice(1)||'reiseinfos').split('?')[0];page=({uebersicht:'reiseinfos',route:'programm',crew:'gruppe',reiseideen:'programm'})[page]||page;const view=['reiseinfos','programm','routen','hotels','anreise','mietwagen','reiseplan','unterlagen','termine','fotos','gruppe','planung'].includes(page)?page:'reiseinfos';if($('#idea-detail-dialog').open)$('#idea-detail-dialog').close();$$('[data-view]').forEach(x=>x.hidden=x.dataset.view!==view);$$('[data-nav]').forEach(x=>{if(x.dataset.nav===view)x.setAttribute('aria-current','page');else x.removeAttribute('aria-current');});document.title=({reiseinfos:'Howdy Texas',programm:'Unsere Reiseideen',routen:'Routenvorschläge',hotels:'Unsere Hotelideen',anreise:'Anreise & Flüge',mietwagen:'Mietwagen',reiseplan:'Unser Reiseplan',unterlagen:'Reiseunterlagen',termine:'Terminabstimmung',fotos:'Unsere Fotos',gruppe:'Unsere Gruppe',planung:'Unsere Planung'})[view]+' · Roadtrip';if(scroll)$('.view-nav').scrollIntoView({behavior:'instant',block:'start'});}
function openLogin(){ $('#login-error').textContent='';$('#login-submit').disabled=config.backendReady&&!client;$('#login-form').hidden=!config.backendReady;$('#setup-message').hidden=config.backendReady;$('#login-intro').hidden=!config.backendReady;$('#login-dialog').showModal();}
function budget(){const draft=readForm(),b=draft.budget,n=BUDGET_KEYS.filter(k=>b[k]!==null).length,t=totalBudget(b,draft.days);$('#budget-total').textContent=n?euro.format(t):'–';$('#budget-person').textContent=n?euro.format(t/4):'–';$('#budget-hint').textContent='Schätzung für 4 Personen und '+draft.days+' Tage vor Ort. '+(n?n+'/7 Kostenfelder ausgefüllt. '+(n<7?'Leere Felder fehlen noch.':'Keine bestätigten Angebote.'):'Eigene Schätzwerte eintragen.');}
function readForm(){const f=$('#plan-form'),raw={start:f.elements.start.value,days:Number(f.elements.days.value),note:f.elements.note.value,tasks:{},budget:{}};TASKS.forEach(([id])=>raw.tasks[id]=f.elements['task-'+id].checked);BUDGET_KEYS.forEach(k=>{const el=f.elements[k];raw.budget[k]=el.value===''||!el.validity.valid?null:Number(el.value);});return cleanState(raw);}
function renderPlan(){const f=$('#plan-form');f.elements.start.value=plan.start;f.elements.days.value=plan.days;f.elements.note.value=plan.note;TASKS.forEach(([id])=>f.elements['task-'+id].checked=plan.tasks[id]);BUDGET_KEYS.forEach(k=>f.elements[k].value=plan.budget[k]??'');$('#date-summary').textContent=plan.start?date():'Ab 22.04.2027';$('#date-detail').textContent=plan.start?date()+' bis '+date(plan.days-1)+' · gemeinsamer Terminvorschlag.':'Terminvorschlag noch offen. Frühestens ab 22.04.2027, maximal 14 Tage inklusive An- und Rückreise.';dirty=false;$('#sync-status').closest('.sync-bar').dataset.dirty='false';budget();}
function renderGroup(){if(!context)return;$('#people').innerHTML=context.people.map(p=>'<article class="person"><div class="avatar" aria-hidden="true">'+esc(p.name.split(' ').map(x=>x[0]).join(''))+'</div><h3>'+esc(p.name)+'</h3><p class="booking-status">Fest dabei ✓</p><small>'+(p.key===context.me?'Du bist angemeldet':'Teil unserer Crew')+'</small></article>').join('');
 $('#group-votes').innerHTML=ideas.filter(i=>!i.archived&&count(i)).sort((a,b)=>count(b)-count(a)).map(i=>'<div class="vote-summary"><button class="quiet" data-detail="'+esc(i.id)+'">'+esc(i.title)+' · '+(i.kind==='hotel'?'Hotel':'Reiseziel')+'</button><small>'+votes.filter(v=>v.idea_id===i.id).map(v=>esc(context.people.find(p=>p.key===v.member_key)?.name||'Crewmitglied')).join(', ')+'</small></div>').join('')||'<p class="muted">Noch keine Favoriten. Bei Reiseideen und Hotels auf das Herz klicken.</p>';
 const archived=ideas.filter(i=>i.archived&&i.author_key===context.me);$('#withdrawn-panel').hidden=!archived.length;$('#withdrawn').innerHTML=archived.map(i=>'<div class="vote-summary"><b>'+esc(i.title)+'</b><button class="quiet" data-restore="'+esc(i.id)+'">Wieder aufnehmen →</button></div>').join('');
}
function clearPrivate(){context=null;hub.clear();votes=[];ideas=IDEAS.map(i=>({...i}));revision=null;plan=cleanState({});dirty=false;editorDirty=false;editing=null;for(const id of ['idea-dialog','idea-detail-dialog'])if($('#'+id).open)$('#'+id).close();$$('.protected').forEach(x=>x.hidden=true);$$('.private-gate').forEach(x=>x.hidden=false);$('#whoami').textContent='';$('#account-button').textContent='Anmelden →';$('#people').replaceChildren();$('#group-votes').replaceChildren();$('#withdrawn').replaceChildren();renderPlan();renderCatalog();}
async function allRows(table,columns){let rows=[];for(let offset=0;;offset+=1000){const r=await client.from(table).select(columns).order(table==='howdy_ideas'?'id':'idea_id').range(offset,offset+999);if(r.error)throw Error('Die gemeinsame Ideensammlung konnte nicht geladen werden.');rows.push(...r.data);if(r.data.length<1000)return rows;}}
async function loadCatalog(){if(!context)return;const current=context;const [items,marks]=await Promise.all([allRows('howdy_ideas','id,kind,title,location,region,description,url,photo_key,author_key,archived,revision,created_at'),allRows('howdy_idea_votes','member_key,idea_id')]);if(context!==current)return;ideas=items;votes=marks;renderCatalog();}
async function loadPlan(){const current=context;const {data,error}=await client.from('howdy_plan').select('data,revision,updated_at').eq('id',1).single();if(error||!data)throw Error('Planung konnte nicht geladen werden. Bitte erneut versuchen.');if(context!==current)return;plan=cleanState(data.data);revision=data.revision;renderPlan();$('#sync-status').textContent='Gemeinsamer Stand · '+new Date(data.updated_at).toLocaleString('de-AT');}
async function enter(){const result=await client.rpc('howdy_context');if(result.error)throw Error('Gruppenbereich momentan nicht erreichbar.');if(!result.data?.me)throw Error('Dieser Zugang gehört nicht zur Texas-Reisegruppe.');context=result.data;try{await Promise.all([loadPlan(),loadCatalog(),hub.load()]);}catch(e){clearPrivate();throw e;}$$('.protected').forEach(x=>x.hidden=false);$$('.private-gate').forEach(x=>x.hidden=true);$('#whoami').textContent=context.name;$('#account-button').textContent='Abmelden';renderGroup();}
async function invoke(body){const r=await client.functions.invoke(config.functionName,{body});if(r.error){let msg='Dienst momentan nicht erreichbar.';try{msg=(await r.error.context.json()).error||msg;}catch{}throw Error(msg);}if(!r.data?.ok)throw Error(r.data?.error||'Anmeldung fehlgeschlagen.');return r.data;}
async function signIn(name,code){if(!client)throw Error('Anmeldung wird noch geladen. Bitte kurz warten.');let {data}=await client.auth.getSession();if(!data.session){const a=await client.auth.signInAnonymously();if(a.error)throw Error('Anmeldung konnte nicht gestartet werden.');}await invoke({name,code});await enter();}
function previewPhoto(){const p=PHOTOS[$('#photo-select').value]||PHOTOS.roadtrip;$('#photo-preview').innerHTML='<img src="'+esc(p.url)+'" alt="'+esc(p.label)+'" referrerpolicy="no-referrer"><span>'+esc(p.label)+'</span>';}
function openIdea(kind,id=null){if(!context){pendingKind=kind;openLogin();return;}const i=id?ideas.find(x=>x.id===id&&x.author_key===context.me):null;if(id&&!i)return;editing=i?{...i}:null;const f=$('#idea-form');f.reset();for(const k of ['kind','region','title','location','description','url','photo_key'])if(i)f.elements[k].value=i[k];if(!i){f.elements.kind.value=kind;f.elements.photo_key.value='roadtrip';}$('#idea-form-title').textContent=i?'Deinen Vorschlag bearbeiten.':'Deine Idee für den Trip.';$('#idea-error').textContent='';editorDirty=false;previewPhoto();$('#idea-dialog').showModal();}
async function setArchived(id,archived){if(!context)return;const i=ideas.find(x=>x.id===id&&x.author_key===context.me);if(!i)return;const r=await client.from('howdy_ideas').update({archived,revision:nextRevision(i.revision)}).eq('id',id).eq('revision',i.revision).select('id,revision,archived');if(r.error||r.data?.length!==1)throw Error('Vorschlag inzwischen geändert oder Speichern fehlgeschlagen. Bitte die Sammlung aktualisieren.');Object.assign(i,r.data[0]);renderCatalog();toast(archived?'Vorschlag zurückgezogen. Unter „Unsere Gruppe“ kannst du ihn wieder aufnehmen.':'Vorschlag wieder für alle sichtbar.');}
$('#task-list').innerHTML=TASKS.map(([id,title,note])=>'<label class="task-label"><input type="checkbox" name="task-'+id+'"><span><b>'+esc(title)+'</b><small>'+esc(note)+'</small></span></label>').join('');
$('#budget-inputs').innerHTML=BUDGET_KEYS.map(k=>'<label>'+labels[k]+'<input type="number" name="'+k+'" min="0" max="100000" step="0.01" inputmode="decimal"></label>').join('');
$('#photo-select').innerHTML=Object.entries(PHOTOS).map(([key,p])=>'<option value="'+key+'">'+esc(p.label)+'</option>').join('');
$('#photo-credits').innerHTML=Object.values(PHOTOS).map(p=>'<li>'+esc(p.label)+' · <a href="'+esc(p.source)+'" target="_blank" rel="noopener noreferrer">'+esc(p.author)+'</a> · <a href="'+esc(p.licenseUrl)+'" target="_blank" rel="noopener noreferrer">'+esc(p.license)+'</a></li>').join('');
document.addEventListener('click',async e=>{
 const close=e.target.closest('[data-close]');if(close){if(close.dataset.close==='idea-dialog'&&(ideaSaving||(editorDirty&&!confirm('Ungespeicherten Vorschlag verwerfen?'))))return;$('#'+close.dataset.close).close();return;}
 const add=e.target.closest('[data-add]');if(add){openIdea(add.dataset.add);return;}
 const detail=e.target.closest('[data-detail]');if(detail){showDetail(detail.dataset.detail);return;}
 const edit=e.target.closest('[data-edit]');if(edit){openIdea('destination',edit.dataset.edit);return;}
 const b=e.target.closest('[data-vote],[data-archive],[data-restore]');if(!b)return;if(!context){openLogin();return;}b.disabled=true;
 try{if(b.dataset.archive)await setArchived(b.dataset.archive,true);else if(b.dataset.restore)await setArchived(b.dataset.restore,false);else{const i=ideas.find(x=>x.id===b.dataset.vote);if(!i)return;const wasMine=mine(i);const r=wasMine?await client.from('howdy_idea_votes').delete().eq('member_key',context.me).eq('idea_id',i.id):await client.from('howdy_idea_votes').insert({member_key:context.me,idea_id:i.id});if(r.error)throw Error('Favorit wurde nicht gespeichert. Bitte erneut versuchen.');votes=votes.filter(v=>!(v.member_key===context.me&&v.idea_id===i.id));if(!wasMine)votes.push({member_key:context.me,idea_id:i.id});renderCatalog();}}
 catch(err){toast(err.message);}finally{b.disabled=false;}
});
$('#idea-dialog').addEventListener('cancel',e=>{if(ideaSaving||(editorDirty&&!confirm('Ungespeicherten Vorschlag verwerfen?')))e.preventDefault();});
$('#idea-dialog').addEventListener('close',()=>{editorDirty=false;editing=null;$('#idea-form').reset();});
$('#idea-form').addEventListener('input',()=>{editorDirty=true;});$('#photo-select').addEventListener('change',previewPhoto);
$('#idea-form').addEventListener('submit',async e=>{e.preventDefault();if(!context||ideaSaving)return;ideaSaving=true;$('#save-idea').disabled=true;$('#idea-error').textContent='';try{const draft=validateIdea(Object.fromEntries(new FormData(e.target)));const current=editing;const r=current?await client.from('howdy_ideas').update({...draft,revision:nextRevision(current.revision)}).eq('id',current.id).eq('revision',current.revision).select():await client.from('howdy_ideas').insert({...draft,author_key:context.me}).select();if(r.error)throw Error('Speichern fehlgeschlagen. Deine Eingaben bleiben stehen.');if(r.data?.length!==1)throw Error('Dieser Vorschlag wurde inzwischen geändert. Deine Eingaben bleiben stehen. Kopiere sie und lade die Sammlung neu.');ideas=ideas.filter(i=>i.id!==r.data[0].id);ideas.push(r.data[0]);filter='all';$$('[data-filter]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.filter==='all')));$('#destination-search').value='';$('#hotel-search').value='';editorDirty=false;$('#idea-dialog').close();location.hash=draft.kind==='hotel'?'hotels':'programm';renderCatalog();toast('Dein Vorschlag ist für die Gruppe gespeichert.');}catch(err){$('#idea-error').textContent=err.message;}finally{ideaSaving=false;$('#save-idea').disabled=false;}});
$$('[data-open-login]').forEach(b=>b.addEventListener('click',openLogin));
$('#show-password').addEventListener('change',e=>$('#login-code').type=e.target.checked?'text':'password');
$('#login-dialog').addEventListener('close',()=>{$('#login-code').value='';$('#login-code').type='password';$('#show-password').checked=false;if(!context)pendingKind=null;});
$('#account-button').addEventListener('click',async()=>{if(!context){openLogin();return;}if(hub.isBusy()){toast('Bitte die laufende Übertragung abwarten.');return;}if((dirty||editorDirty||hub.isDirty())&&!confirm('Ungespeicherte Änderungen verwerfen und abmelden?'))return;const revoked=await client.rpc('howdy_logout');await client.auth.signOut({scope:'local'});clearPrivate();toast(revoked.error?'Lokal abgemeldet. Die Serversitzung konnte gerade nicht beendet werden.':'Abgemeldet.');});
$('#login-form').addEventListener('submit',async e=>{e.preventDefault();if(!config.backendReady)return;$('#login-submit').disabled=true;$('#login-error').textContent='';try{await signIn($('#login-name').value,$('#login-code').value);$('#login-dialog').close();toast('Howdy, '+context.name.split(' ')[0]+'!');if(pendingKind){const kind=pendingKind;pendingKind=null;openIdea(kind);}}catch(err){clearPrivate();$('#login-error').textContent=err.message;}finally{$('#login-submit').disabled=false;}});
$$('[data-filter]').forEach(b=>b.addEventListener('click',()=>{filter=b.dataset.filter;$$('[data-filter]').forEach(x=>x.setAttribute('aria-pressed',String(x.dataset.filter===filter)));renderCatalog();}));
for(const id of ['destination-search','hotel-search'])$('#'+id).addEventListener('input',renderCatalog);
$$('[data-refresh]').forEach(b=>b.addEventListener('click',async()=>{if(!context){openLogin();return;}b.disabled=true;try{await Promise.all([loadCatalog(),hub.load()]);toast('Vorschläge und Favoriten aktualisiert.');}catch(e){toast(e.message);}finally{b.disabled=false;}}));
$('#plan-form').addEventListener('input',()=>{dirty=true;$('#sync-status').closest('.sync-bar').dataset.dirty='true';$('#sync-status').textContent='Ungespeicherte Änderungen';budget();});
$('#plan-form').addEventListener('submit',async e=>{e.preventDefault();if(!context||saving||revision===null)return;saving=true;$('#save-plan').disabled=true;const draft=readForm();try{const r=await client.from('howdy_plan').update({data:draft,revision:nextRevision(revision)}).eq('id',1).eq('revision',revision).select('revision,updated_at');if(r.error)throw Error('Speichern fehlgeschlagen. Deine Eingaben bleiben stehen.');if(r.data?.length!==1)throw Error('Inzwischen hat jemand den Plan geändert. Deine Eingaben bleiben stehen. Kopiere sie bei Bedarf und lade den neuen Stand.');plan=draft;revision=r.data[0].revision;renderPlan();$('#sync-status').textContent='Für alle gespeichert · '+new Date(r.data[0].updated_at).toLocaleString('de-AT');toast('Gemeinsame Planung gespeichert.');}catch(err){$('#sync-status').textContent=err.message;toast(err.message);}finally{saving=false;$('#save-plan').disabled=false;}});
$('#reload-plan').addEventListener('click',async()=>{if(dirty&&!confirm('Deine ungespeicherten Eingaben verwerfen und den gemeinsamen Stand laden?'))return;try{await Promise.all([loadPlan(),loadCatalog(),hub.load()]);}catch(e){toast(e.message);}});
window.addEventListener('beforeunload',e=>{if(dirty||editorDirty||hub.isDirty()||hub.isBusy()){e.preventDefault();e.returnValue='';}});window.addEventListener('hashchange',()=>route());
renderRoutes();renderPlan();renderCatalog();route(false);
if(config.backendReady){try{const {createClient}=await import('https://esm.sh/@supabase/supabase-js@2.57.4');client=createClient(config.url,config.publicKey,{auth:{storageKey:'howdy-texas-auth-v2',detectSessionInUrl:false,persistSession:true,autoRefreshToken:true}});$('#login-submit').disabled=false;client.auth.onAuthStateChange(event=>{if(event==='SIGNED_OUT')clearPrivate();});const {data}=await client.auth.getSession();if(data.session)await enter();}catch(err){clearPrivate();toast(err.message||'Anmeldung momentan nicht erreichbar.');}}

